// Parameter destructuring patterns that lose reactivity

// Basic parameter destructuring
export default {
  setup({ foo, bar }) {
    return () => h('div', foo + bar)
  }
}

// Destructuring with default values  
export default {
  setup({ foo = 'default', bar }) {
    return () => h('div', foo + bar)
  }
}

// Destructuring with renaming
export default {
  setup({ foo: renamedFoo, bar }) {
    return () => h('div', renamedFoo + bar)
  }
}

// Destructuring with rest pattern
export default {
  setup({ foo, ...rest }) {
    return () => h('div', foo + rest.bar)
  }
}

// defineComponent with parameter destructuring
export default defineComponent({
  setup({ foo, bar }) {
    return () => h('div', foo + bar)
  }
})

// Named export with parameter destructuring  
export const MyComponent = {
  setup({ foo, bar }) {
    return () => h('div', foo + bar)
  }
}

// Invalid: basic parameter destructuring
export default {
  setup({ count }) {
    return () => h('div', count);
  }
}

/* should not generate diagnostics */

// Valid cases for non-Vue contexts that should be ignored

// Non-setup function should be ignored
export default {
  notSetup({ foo }) {
    return () => h('div', foo)
  }
}

// Regular object (not Vue component) should be ignored
const regularObject = {
  setup({ foo }) {
    return () => h('div', foo)
  }
};

// Function not in Vue component context
function regularFunction({ foo }) {
  const { bar } = foo;
  return bar;
}

// Class method
class MyClass {
  setup({ foo }) {
    const { bar } = foo;
    return bar;
  }
}

// Standalone arrow function
const myFunc = ({ foo }) => {
  const { bar } = foo;
  return bar;
};

/* should not generate diagnostics */

// Valid: using props parameter directly
export default {
  setup(props) {
    return () => h('div', props.count)
  }
}
